import type { Command } from './types.js';
 export function nextEnabledIndex(commands: Command[], current: number, step: 1 | -1) {
   const size = commands.length;
   for (let offset = 1; offset <= size; offset++) {
     const candidate = (current + offset * step + size * 2) % size;
     if (!commands[candidate].disabled) return candidate;
   }
   return current;
 }

