import { nextEnabledIndex } from './navigation.js';
 import type { Command } from './types.js';
 export function moveSelection(commands: Command[], index: number, key: string) {
   if (key === 'ArrowDown') return nextEnabledIndex(commands, index, 1);
   if (key === 'ArrowUp') return nextEnabledIndex(commands, index, -1);
   return index;
 }
 export function chooseCommand(command: Command, onSelect: (id: string) => void) {
   if (!command.disabled) onSelect(command.id);
 }

